using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
namespace Deception.Tests
{
 public static partial class BlackoutTests
 {
  static int Assertions;static readonly List<string> Cases=new();
  static void Check(bool yes,string why){Assertions++;if(!yes)throw new Exception(why);}
  static void Test(string name,Action action){try{Fault.At="";NativeRogueSight.Clear();NativeBlackout.Clear();NativeRegroupSession.Owned.Clear();NativeGameStateEnvelope.Values.Clear();RecruitmentHooks.Registered=true;action();Cases.Add(name);}catch(Exception e){throw new Exception(name,e);}}
  static LedgerAppearance Mask()=>new("warrior",new("imperius","default"),new("imperius","default"),new("imperius","default"),7,100,100,false,ApparentConcealment.Visible,-1,Array.Empty<string>());
  static TileData Tile(GameState s,int x,int y)=>MapDataExtensions.GetTile(s.Map,new(x,y))!;
  static UnitState Add(GameState s,uint id,int x,int y,byte owner=1,UnitType type=UnitType.dcp_spy)
  {var u=new UnitState{id=id,owner=owner,type=type,coordinates=new(x,y),UnitData=new(){type=type}};Tile(s,x,y).unit=u;return u;}
  static NativeIdentityLedger Read(GameState s){var v=NativeGameStateEnvelope.Get(s)!;return NativeIdentityLedgerCodec.Decode(v.Bytes(),v.Revision);}
  static void Write(GameState s,NativeIdentityLedger ledger){var v=NativeGameStateEnvelope.Get(s)!;NativeGameStateEnvelope.Set(s,v.Revision,NativeIdentityLedgerCodec.Encode(ledger,v.Revision));NativeBlackout.Bind(s);}
  static GameState Make(bool chain=false,bool disguise=false)
  {
   var s=new GameState();s.Map.Tiles.Values=(from y in Enumerable.Range(0,8)from x in Enumerable.Range(0,12)select new TileData{coordinates=new(x,y)}).ToArray();
   foreach(byte p in new byte[]{1,2,3}){s.PlayerStates.Add(new(){Id=p,Treaty=p==3});foreach(var t in s.Map.Tiles.Values)t.explorers!.Add(p);}
   // Most historical fog cases start with the final remaining Blackout (no DoubleReady).
   Add(s,1,1,1,type:UnitType.dcp_motherfogger);if(chain){Add(s,2,3,1);Add(s,3,5,1);Add(s,4,3,3);}
   var units=s.Map.Tiles.Values.Where(t=>t.unit is not null).Select(t=>new LedgerUnit(t.unit!.id,t.unit.id,true,LedgerActualKind.Genuine,disguise,disguise?Mask():null,PaidInvestmentKind.Known,8)).ToArray();
   var ledger=new NativeIdentityLedger(Guid.Parse("76c18aa1-cd76-476f-a08e-79d1bf5968ec"),100,1,units,Array.Empty<LedgerReceipt>());
   NativeGameStateEnvelope.Set(s,0,NativeIdentityLedgerCodec.Encode(ledger,0));NativeRegroupSession.Owned.Add(s);return s;
  }
  static NativeExchangeIntent Offer(GameState s,int x,int y){Check(NativeBlackout.TryOffer(s,1,x,y,out var i,out var why),why);return i!;}
  static void Cast(GameState s,int x,int y){var i=Offer(s,x,y);Check(NativeBlackout.TryCommit(s,i,out var r,out var why),why);Check(r is not null&&!r.AlreadyCommitted,"first cast committed");}
  static void RefreshSource(GameState s,SourceAction action,Action body)
  {
   s.ActionStack.Add(action);NativeBlackoutDiscovery.BeforeSource(action,s,action.GetType().GetMethod("Execute")!,out var scope);Exception? error=null;
   try{body();NativeBlackoutDiscovery.AfterSource(true,scope);}catch(Exception e){error=e;throw;}finally{var final=NativeBlackoutDiscovery.SourceFinished(error,scope);if(final is not null&&error is null)throw final;}
  }
  static void Execute(GameState s,ExploreAction action)
  {
   bool valid=action.IsValid(s);NativeBlackoutDiscovery.AfterValid(action,s,ref valid);Check(valid,"queued discovery is valid");
   NativeRogueSight.BeforeExplore(action,s,out var rogue);bool run=NativeBlackoutDiscovery.BeforeExecute(action,s,out var scope);Check(run,"queued discovery enters native execution");Exception? error=null;
   try{action.Execute(s);NativeBlackoutDiscovery.AfterExecute(scope);NativeRogueSight.AfterExplore(true,rogue);}catch(Exception e){error=e;throw;}finally{NativeRogueSight.ExploreFinished(error,rogue);var final=NativeBlackoutDiscovery.ExecuteFinished(error,scope);if(final is not null&&error is null)throw final;}
  }
  static ExploreAction Pending(GameState s,byte player,int x,int y)=>Native.Items(s.ActionStack).OfType<ExploreAction>().Last(a=>a.PlayerId==player&&a.Coordinates.X==x&&a.Coordinates.Y==y);
  public static int Run(){try{
   Test("blackout-every-other-player-including-peace-and-empty-tile",()=>{var s=Make();var target=Tile(s,2,1);var old=target.explorers;Cast(s,2,1);Check(target.GetExplored(1)&&!target.GetExplored(2)&&!target.GetExplored(3),"only caster mask retained");Check(old!.Contains(2)&&!ReferenceEquals(old,target.explorers),"native mask uses detached list");Check(Read(s).Blackouts!.Length==2,"persistent per-player marks");Check(Native.Items(s.PlayerStates).Cast<PlayerState>().All(p=>p.Currency==37&&p.Treaty==(p.Id==3)),"no stars or treaty change");});
   Test("caster-unexplored-and-everyone-already-fogged-valid",()=>{var s=Make();Tile(s,2,1).explorers=new();Cast(s,2,1);Check(!Tile(s,2,1).GetExplored(1)&&Read(s).Blackouts!.Length==2,"caster fog unchanged, same successful shape");});
   Test("only-initiator-spends-and-reveals",()=>{var s=Make(true,true);var a=Tile(s,1,1).unit!;var b=Tile(s,3,1).unit!;b.moved=true;b.effects.Add(UnitEffect.Poisoned);Cast(s,2,1);Check(a.moved&&a.attacked&&!b.attacked&&b.moved,"neighbor pays no action");Check(!Read(s).Units.Single(u=>u.NativeId==1).Independent&&Read(s).Units.Where(u=>u.NativeId!=1).All(u=>u.Independent),"only initiating disguise removed");Check(b.effects.Contains(UnitEffect.Poisoned)&&b.health==100,"neighbor effects/body unchanged");});
   foreach(var type in new[]{UnitType.dcp_spy,UnitType.dcp_spymaid})foreach(string status in new[]{"ready","spent","moved","frozen","disguised"})Test("neighbor-never-extends-range-"+type+"-"+status,()=>{var s=Make(true,status=="disguised");var u=Tile(s,3,1).unit!;u.type=type;u.moved=status is "spent" or "moved";u.attacked=status=="spent";if(status=="frozen")u.effects.Add(UnitEffect.Frozen);var before=NativeGameStateEnvelope.Get(s)!;Check(NativeBlackout.TryOffer(s,1,3,3,out _,out _),"native diagonal range-two remains valid");Check(!NativeBlackout.TryOffer(s,1,4,1,out _,out _)&&!NativeBlackout.TryOffer(s,1,7,1,out _,out _),"neither one hop nor many hops extend reach");Check(ReferenceEquals(before,NativeGameStateEnvelope.Get(s))&&!Tile(s,1,1).unit!.attacked,"range queries do not spend or publish");});
   foreach(string status in new[]{"spent","frozen","dead","linked","foreign","fake","covered","unexplored","out-of-turn"})Test("invalid-initiator-"+status,()=>{var s=Make();var u=Tile(s,1,1).unit!;switch(status){case"spent":u.attacked=true;break;case"frozen":u.effects.Add(UnitEffect.Frozen);break;case"dead":u.health=0;break;case"linked":u.Linked=true;break;case"foreign":u.owner=2;break;case"fake":u.type=UnitType.dcp_mimic_form_dcp_spy;break;case"covered":Write(s,Read(s) with{Blackouts=new[]{new LedgerBlackout(1,1,1)}});break;case"unexplored":Tile(s,1,1).explorers=new();break;case"out-of-turn":s.CurrentPlayer=2;break;}Check(!NativeBlackout.TryOffer(s,1,2,1,out _,out _),"invalid source not offered");});
   Test("moved-fogger-can-cast-with-dash",()=>{var s=Make();var u=Tile(s,1,1).unit!;u.moved=true;var before=NativeGameStateEnvelope.Get(s)!;Check(NativeBlackout.TryOffer(s,1,2,1,out _,out _),"moved Fogger retains Dash action");Check(u.moved&&!u.attacked&&ReferenceEquals(before,NativeGameStateEnvelope.Get(s))&&Tile(s,2,1).GetExplored(2),"denied offer preserves flags, fog and ledger");});
   Test("moving-after-blackout-targeting-invalidates-commit",()=>{var s=Make();var i=Offer(s,2,1);Tile(s,1,1).unit!.moved=true;Tile(s,1,1).unit!.coordinates=new(0,1);var before=NativeGameStateEnvelope.Get(s)!;Check(!NativeBlackout.TryCommit(s,i,out _,out _),"stale stationary offer cannot cast after moving");Check(ReferenceEquals(before,NativeGameStateEnvelope.Get(s))&&Tile(s,2,1).GetExplored(2),"stale cast has no fog or ledger effect");});
   Test("allied-spy-cycle-does-not-expand-direct-area",()=>{var s=Make(true);Check(NativeSpyNetwork.TryFoggerReachable(s,1,1,out var tiles,out _),"direct area evaluated");var expected=MapDataExtensions.GetAreaSorted(s.Map,new(1,1),2,true,true).Values;Check(tiles.Distinct().Count()==tiles.Length&&tiles.Cast<TileData>().SequenceEqual(expected),"only native source area despite cyclic neighboring Spies");Cast(s,3,3);Check(Read(s).Receipts.Length==1,"one receipt for direct cast");});
   Test("fake-middle-node-does-not-extend-range",()=>{var s=Make(true);Tile(s,3,1).unit!.type=UnitType.dcp_mimic_form_dcp_spy;Tile(s,3,3).unit!.type=UnitType.dcp_mimic_form_dcp_spy;Check(!NativeBlackout.TryOffer(s,1,7,1,out _,out _),"apparent Spy supplies no additional range");});
   Test("neighbor-discovery-never-extends-range",()=>{var s=Make(true);Write(s,Read(s) with{Blackouts=new[]{new LedgerBlackout(1,3,1),new LedgerBlackout(1,3,3)}});Check(!NativeBlackout.TryOffer(s,1,7,1,out _,out _),"covered neighbor gives no extra reach");Write(s,Read(s) with{Blackouts=Array.Empty<LedgerBlackout>()});Tile(s,3,1).unit!.attacked=true;Check(!NativeBlackout.TryOffer(s,1,7,1,out _,out _),"rediscovered neighbor still gives no extra reach");});
   Test("current-and-expired-rogue-spies-never-extend-range",()=>{var s=Make(true);Tile(s,3,1).unit!.type=UnitType.dcp_motherfogger;Write(s,Read(s) with{Units=Read(s).Units.Select(u=>u.NativeId==2||u.NativeId==4?u with{Rogue=new(2,1,s.CurrentTurn)}:u).ToArray()});Check(!NativeBlackout.TryOffer(s,1,7,1,out _,out _),"acquired genuine Spy does not extend another Spy");Check(NativeBlackout.TryOffer(s,2,5,2,out _,out _),"acquired Spy can use its own direct area");s.CurrentTurn++;Check(!NativeBlackout.TryOffer(s,2,5,2,out _,out _),"expired command cannot initiate");});
   foreach(string change in new[]{"source-death","source-freeze","turn","owner","disguise","source-move"})Test("commit-revalidates-"+change,()=>{var s=Make(true);var i=Offer(s,2,1);switch(change){case"source-death":Tile(s,1,1).unit!.health=0;break;case"source-freeze":Tile(s,1,1).unit!.effects.Add(UnitEffect.Frozen);break;case"turn":s.CurrentTurn++;break;case"owner":s.CurrentPlayer=2;break;case"disguise":Write(s,Read(s) with{Units=Read(s).Units.Select(u=>u.NativeId==1?u with{Independent=true,Appearance=Mask()}:u).ToArray()});break;case"source-move":Tile(s,1,1).unit!.coordinates=new(0,0);break;}Check(!NativeBlackout.TryCommit(s,i,out _,out _),"stale source or intent rejected before spend");Check(!Tile(s,1,1).unit!.attacked&&Tile(s,2,1).GetExplored(2),"failed intent has no effect");});
   Test("legacy-relay-distance-intent-rejected-at-commit",()=>{var s=Make(true);var local=Offer(s,2,1);var remote=local with{Partner=local.Partner with{X=7,Y=1}};var before=NativeGameStateEnvelope.Get(s)!;Check(!NativeBlackout.TryCommit(s,remote,out _,out _),"validly framed old-range request is rejected");Check(ReferenceEquals(before,NativeGameStateEnvelope.Get(s))&&!Tile(s,1,1).unit!.attacked&&Tile(s,7,1).GetExplored(2),"no spend, fog or publication on rejected request");});
   Test("receipt-retry-is-noop-and-recast-has-no-stack",()=>{var s=Make();var i=Offer(s,2,1);Check(NativeBlackout.TryCommit(s,i,out _,out _),"commit");var snap=NativeGameStateEnvelope.Get(s)!;Check(NativeBlackout.TryCommit(s,i,out var result,out _)&&result!.AlreadyCommitted,"retry recognized");Check(ReferenceEquals(snap,NativeGameStateEnvelope.Get(s)),"retry does not publish/spend again");Tile(s,1,1).unit!.attacked=false;Tile(s,1,1).unit!.moved=false;Cast(s,2,1);Check(Read(s).Blackouts!.Length==2&&Read(s).Receipts.Length==2,"new valid action replaces same marks without duration stack");});
   foreach(string stage in new[]{"exhaust","fog","validate","ledger"})Test("exact-rollback-"+stage,()=>{var s=Make(disguise:true);var i=Offer(s,2,1);var old=NativeGameStateEnvelope.Get(s)!;var unit=Tile(s,1,1).unit!;var effects=unit.effects;var mask=Tile(s,2,1).explorers;Fault.At=stage;Check(!NativeBlackout.TryCommit(s,i,out _,out _),"injected failure refuses");Check(!unit.moved&&!unit.attacked&&ReferenceEquals(effects,unit.effects)&&ReferenceEquals(mask,Tile(s,2,1).explorers),"exact native preimages restored");Check(NativeGameStateEnvelope.Get(s)!.Bytes().SequenceEqual(old.Bytes())&&NativeGameStateEnvelope.Get(s)!.Revision==old.Revision,"exact ledger restored");});
   Test("ordinary-mask-remains-fogged-through-static-recompute",()=>{var s=Make();Cast(s,2,1);Tile(s,2,1).SetExplored(2,true);Check(!Tile(s,2,1).GetExplored(2),"unscoped native setter cannot lift Blackout");ActionUtils.ExploreFromTile(s,(PlayerState)Native.Items(s.PlayerStates).ElementAt(1),Tile(s,1,1),2,true);Check(!Native.Items(s.ActionStack).OfType<ExploreAction>().Any(a=>a.PlayerId==2&&a.Coordinates.X==2&&a.Coordinates.Y==1),"unapproved growth/static sight cannot queue covered discovery");});
   Test("new-movement-authorizes-native-discovery-and-only-one-player-clears",()=>{var s=Make();Cast(s,2,1);s.CurrentPlayer=2;var u=Add(s,20,2,2,2);var p=(PlayerState)Native.Items(s.PlayerStates).ElementAt(1);RefreshSource(s,new MoveAction{PlayerId=2,UnitId=20},()=>ActionUtils.ExploreFromTile(s,p,Tile(s,2,2),2,true));Check(Read(s).Discoveries!.Any(d=>d.Player==2&&d.X==2&&d.Y==1)&&!Tile(s,2,1).GetExplored(2),"permit persists while native reveal remains queued");Execute(s,Pending(s,2,2,1));Check(Tile(s,2,1).GetExplored(2)&&!Tile(s,2,1).GetExplored(3),"players rediscover independently");Check(Read(s).Blackouts!.Single().Player==3&&Read(s).Discoveries!.Length==0,"consume only entitled marker/permit");Check(!u.attacked&&!u.moved,"rescue does not spend rescued allowance in custom adapter");});
   foreach(string source in new[]{"train","convert","rule-area","embassy"})Test("native-discovery-source-"+source,()=>{var s=Make();Cast(s,2,1);s.CurrentPlayer=2;Add(s,20,2,2,2);var p=(PlayerState)Native.Items(s.PlayerStates).ElementAt(1);SourceAction action=source switch{"train"=>new TrainAction{Coordinates=new(2,2)},"convert"=>new ConvertAction{Origin=new(2,2)},"rule-area"=>new RuleAreaAction{Coordinates=new(2,2)},_=>new EstablishEmbassyAction()};action.PlayerId=2;RefreshSource(s,action,()=>{if(source is "rule-area" or "embassy")ActionUtils.ExploreTile(s,p,Tile(s,2,1),true);else ActionUtils.ExploreFromTile(s,p,Tile(s,2,2),2,true);});Execute(s,Pending(s,2,2,1));Check(Tile(s,2,1).GetExplored(2),"approved native source clears normal fog");});
   Test("covered-scout-cannot-authorize-its-own-refresh",()=>{var s=Make();Cast(s,2,1);s.CurrentPlayer=2;Add(s,20,2,1,2);var p=(PlayerState)Native.Items(s.PlayerStates).ElementAt(1);RefreshSource(s,new MoveAction{PlayerId=2,UnitId=20},()=>ActionUtils.ExploreFromTile(s,p,Tile(s,2,1),2,true));Check(Read(s).Discoveries!.Length==0&&!Tile(s,2,1).GetExplored(2),"covered own source supplies no permit");});
   Test("unapproved-and-detached-explore-action-cannot-clear",()=>{var s=Make();Cast(s,2,1);var a=new ExploreAction{PlayerId=2,Coordinates=new(2,1)};s.ActionStack.Add(a);bool valid=true;NativeBlackoutDiscovery.AfterValid(a,s,ref valid);Check(!valid&&!NativeBlackoutDiscovery.BeforeExecute(a,s,out _),"queued but unapproved exploration rejected");Write(s,Read(s) with{Discoveries=new[]{new LedgerDiscovery(2,2,1)}});var forged=new ExploreAction{PlayerId=2,Coordinates=new(2,1)};Check(!NativeBlackoutDiscovery.BeforeExecute(forged,s,out _),"matching detached action cannot steal saved permit");});
   Test("saved-permit-survives-state-reconstruction",()=>{var s=Make();Cast(s,2,1);var original=NativeGameStateEnvelope.Get(s)!;var clone=Make();var ledger=NativeIdentityLedgerCodec.Decode(original.Bytes(),original.Revision) with{Discoveries=new[]{new LedgerDiscovery(2,2,1)}};NativeGameStateEnvelope.Set(clone,original.Revision,NativeIdentityLedgerCodec.Encode(ledger,original.Revision));Tile(clone,2,1).explorers=new();NativeBlackout.Bind(clone);var a=new ExploreAction{PlayerId=2,Coordinates=new(2,1)};clone.ActionStack.Add(a);Execute(clone,a);Check(Tile(clone,2,1).GetExplored(2)&&!Tile(s,2,1).GetExplored(2),"saved native child + framed permit belong to reconstructed state only");});
   Test("exchange-stages-provenance-before-atomic-ledger-merge",()=>{var s=Make();Cast(s,2,1);s.CurrentPlayer=2;Add(s,20,2,2,2);var p=(PlayerState)Native.Items(s.PlayerStates).ElementAt(1);var old=NativeGameStateEnvelope.Get(s)!;var collection=new NativeBlackoutDiscovery.Collection();using(NativeBlackoutDiscovery.ExchangeSource(s,2,Tile(s,2,2),collection))ActionUtils.ExploreFromTile(s,p,Tile(s,2,2),2,true);Check(ReferenceEquals(old,NativeGameStateEnvelope.Get(s)),"staging never publishes ledger");var merged=collection.Merge(Read(s));Check(merged.Discoveries!.Single()==new LedgerDiscovery(2,2,1),"caller owns merge into committed candidate");});
   foreach(string command in new[]{"attack","move","train","build","city"})Test("final-command-source-access-"+command,()=>{var s=Make();Cast(s,2,1);CommandBase c=command switch{"attack"=>new AttackCommand{Origin=new(2,1)},"move"=>new MoveCommand{From=new(2,1)},"train"=>new TrainCommand{Coordinates=new(2,1)},"build"=>new BuildCommand{Coordinates=new(2,1)},_=>new CityRewardCommand{Coordinates=new(2,1)}};c.PlayerId=2;Check(!NativeBlackoutAccess.Allowed(c,s,c.GetType()),"source fog blocks direct/stale native command");c.PlayerId=1;Check(NativeBlackoutAccess.Allowed(c,s,c.GetType()),"caster source access unchanged");});
   Test("retaliation-checks-attacker-tile-not-covered-defender-tile",()=>{var s=Make();Cast(s,2,1);var attacker=Tile(s,1,1).unit!;var defender=Add(s,20,2,1,2);bool yes=true;NativeBlackoutAccess.AfterRetaliation(s,attacker,defender,ref yes);Check(yes,"covered defender can still retaliate at visible attacker");attacker.coordinates=new(2,1);yes=true;NativeBlackoutAccess.AfterRetaliation(s,attacker,defender,ref yes);Check(!yes,"defender cannot retaliate against an attacker hidden to that side");});
   SpyStealthCases();
   OwnershipUpgradeCases();
   NativeDiscoveryCases();
   SubvertCases();
   SubvertSightCases();
   UiCases();
   Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Cases.Count,assertions=Assertions,tests=Cases,scope="Actual managed Blackout/network/discovery/access/Subvert adapters against explicit native boundary; no native gameplay acceptance"}));return 0;
  }catch(Exception e){Console.WriteLine(e);return 1;}}
 }
}
